95|/* camera: a slow push-in that follows the work (wide only). Individual translate/scale, so the world's own scale(k) is untouched. */
96|function camera(){
97|  var k=parseFloat(root.style.getPropertyValue('--k'))||1,cx=parseFloat(root.style.getPropertyValue('--cx'))||0,wt=parseFloat(root.style.getPropertyValue('--wt'))||0,vw=root.clientWidth;
98|  var cp=root.querySelector('.hs-copy').getBoundingClientRect(),lim=cp.right+14,rim=vw-12,smax=Math.max(1,(rim-lim)/(746*k));
99|  function f(fx,fy,s){
100|    s=Math.min(s,smax);
101|    var x=(1-s)*k*(fx-380),y=(1-s)*k*fy;if(wt+y<78)y=78-wt;
102|    var xr=cx+x+s*k*366;if(xr>rim)x-=xr-rim;
103|    var xl=cx+x-s*k*380;if(xl<lim)x+=lim-xl;
104|    return{x:x,y:y,s:s};
105|  }
106|  var CE='cubic-bezier(.45,0,.2,1)';
107|  tl.cam(st.querySelector('.hs-cl'),[
108|    [0,f(380,300,1)],[5,f(380,300,1.035),'linear'],[9.4,f(380,300,1),CE],[14.2,f(380,300,1)],[15.4,f(330,170,1.09),CE],[16.8,f(330,170,1.09)],
109|    [18.0,f(160,220,1.14),CE],[20.9,f(160,220,1.14)],[22.1,f(330,150,1.08),CE],[22.9,f(330,150,1.08)],[24.3,f(380,260,1),CE]]);
