148|function build(){
149|  var t=tl.time(),live=tl.master&&tl.master.playState==='running';
150|  tl.clear();fit();mode=NARROW.matches?'narrow':'wide';
151|  root.classList.remove('is-static');root.classList.add('is-live','has-js');
152|  if(mode==='wide')buildWide();else buildNarrow();
153|  tl.master.onfinish=onEnd;
