{"output": "/* Homepage hero: header film v21. Every particle is one task. The frame fills the first screen under the nav on every device.
   The stage has two layouts (landscape 1600x900, portrait 900x1500); the controller picks one and fits it whole. */
@font-face{font-family:'TwTight';src:url('/assets/fonts/InterTight-normal-400-700.woff2') format('woff2');font-weight:400 700;font-display:block}
@font-face{font-family:'TwMono';src:url('/assets/fonts/GeistMono-normal-500.woff2') format('woff2');font-weight:500;font-display:block}
@font-face{font-family:'TwSerif';src:url('/assets/fonts/IBMPlexSerif-italic-400.woff2') format('woff2');font-weight:400;font-style:italic;font-display:block}
.tf{position:relative;padding:var(--nav) 0 0;background:#060807}
.tf-frame{position:relative;width:100%;height:calc(100vh - var(--nav));height:calc(100svh - var(--nav));min-height:420px;max-height:1240px;overflow:hidden;background:#060807;isolation:isolate}
.tf-bg{position:absolute;inset:-80px;background-image:linear-gradient(rgba(236,237,232,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(236,237,232,.05) 1px,transparent 1px);background-size:80px 80px;-webkit-mask-image:radial-gradient(ellipse 60% 55% at 50% 50%,#000 20%,transparent 78%);mask-image:radial-gradient(ellipse 60% 55% at 50% 50%,#000 20%,transparent 78%);will-change:transform}
.tf-glow{position:absolute;left:50%;top:50%;width:120vmax;height:120vmax;margin:-60vmax 0 0 -60vmax;border-radius:50%;background:radial-gradient(circle,rgba(52,211,153,.16) 0,rgba(52,211,153,.06) 26%,rgba(52,211,153,0) 56%);pointer-events:none;will-change:transform,opacity}
.tf-grain{position:absolute;inset:-50%;opacity:.07;pointer-events:none;mix-blend-mode:overlay;animation:tfGrain 1s steps(6) infinite}
.tf-vig{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse 85% 75% at 50% 48%,transparent 55%,rgba(0,0,0,.55) 100%)}
@keyframes tfGrain{0%{transform:translate(0,0)}20%{transform:translate(-3%,2%)}40%{transform:translate(2%,-3%)}60%{transform:translate(-2%,-1%)}80%{transform:translate(3%,3%)}100%{transform:translate(0,0)}}
.tf-gl{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;display:block}
.tf-fit{position:absolute;left:0;top:0;width:1600px;height:900px;transform-origin:0 0}
#tf-stage{position:absolute;inset:0}
#tf-stage>*{position:absolute;left:0;top:0}
#tf-stage svg.full{overflow:visible}
.tf-ctl{position:absolute;right:14px;bottom:12px;z-index:6;display:flex;gap:4px;opacity:.32;transition:opacity .3s}
.tf-ctl:hover,.tf-ctl:focus-within{opacity:.85}
.tf-ctl button{width:32px;height:32px;display:grid;place-items:center;border:0;padding:0;margin:0;background:none;color:#ECEDE8;cursor:pointer;border-radius:50%}
.tf-ctl svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round}
/* type */
.tf-x{font-family:'TwTight','Inter Tight',Inter,sans-serif;font-weight:600;color:#ECEDE8;letter-spacing:-.035em;line-height:1.04;text-align:center;white-space:nowrap}
.tf-x.wrap{white-space:normal}
.tf-x.left{text-align:left}
.tf-m{font-family:'TwMono','Geist Mono',monospace;font-weight:500;color:#A4A9A2;letter-spacing:.14em;text-transform:uppercase;text-align:center;white-space:nowrap;line-height:1.35}
.tf-m.wrap{white-space:normal}
.tf-m.plain{text-transform:none;letter-spacing:.02em}
.tf-b{font-family:'TwTight','Inter Tight',Inter,sans-serif;font-weight:400;color:#A4A9A2;letter-spacing:-.005em;line-height:1.42;text-align:center}
.tf-x .w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .12em;margin:0 -.02em -.12em}
.tf-x .w>i{display:inline-block;font-style:normal;will-change:transform}
.tf-x .em,.tf-em{font-family:'TwSerif','IBM Plex Serif',Georgia,serif;font-style:italic!important;font-weight:400;letter-spacing:-.02em;color:#34D399}
.tf-glowtxt .em{text-shadow:0 0 .35em rgba(52,211,153,.45)}
/* the promise: a light passes through the words */
.tf-sweep .em{background:linear-gradient(100deg,#34D399 0%,#34D399 40%,#F4FFF9 50%,#34D399 60%,#34D399 100%);background-size:300% 100%;background-position:100% 0;-webkit-background-clip:text;background-clip:text;color:transparent}
/* objects */
