const fs = require('fs');
const path = require('path');
const outDir = '/root/.hermes/cache/scratch/motion/frames';
if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });

function saveFrame() {
  const data = renderer.domElement.toDataURL('image/jpeg', 0.95);
  const buf = Buffer.from(data.split(',')[1], 'base64');
  fs.writeFileSync(path.join(outDir, `f${String(frameCount).padStart(4, '0')}.jpg`), buf);
  frameCount++;
  document.getElementById('pct').textContent = Math.round((frameCount / (FPS * DUR)) * 100);
}

// Animate and capture
let lastFrame = -1;
function animate() {
  const elapsed = (performance.now() - startTime) / 1000;
  const t = clamp(elapsed, 0, DUR);
  const frameIdx = Math.floor(t * FPS);
  if (frameIdx > lastFrame && frameIdx < FPS * DUR) {
    renderFrame(t);
    saveFrame();
    lastFrame = frameIdx;
  }
  if (frameIdx >= FPS * DUR) {
    document.getElementById('ui').textContent = 'Done.';
    setTimeout(() => {
      const btn = document.createElement('button');
      btn.textContent = 'CLOSE';
      btn.style.cssText = 'position:fixed;top:20px;right:20px;padding:12px 24px;background:#34D399;color:#050505;border:none;border-radius:4px;font-weight:700;cursor:pointer;z-index:999;';
      btn.onclick = () => window.close();
      document.body.appendChild(btn);
    }, 500);
    return;
  }
  requestAnimationFrame(animate);
}

// Pre-render first frame
renderFrame(0);
saveFrame();
lastFrame = 0;
