{"content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>Twinthos Hero Film</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #050505; }
  canvas { display: block; }
  #ui { position: fixed; bottom: 20px; right: 20px; font-family: monospace; font-size: 12px; color: #9B9B95; z-index: 10; }
</style>
</head>
<body>
<div id="ui">Ready</div>
<script type="importmap">
{
  "imports": {
    "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
    "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';

const W = 1920, H = 1080, FPS = 24, DUR = 20;

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
renderer.setSize(W, H);
renderer.setPixelRatio(1);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
renderer.outputColorSpace = THREE.SRGBColorSpace;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color('#050505');
scene.fog = new THREE.FogExp2('#050505', 0.00012);

const camera = new THREE.PerspectiveCamera(45, W / H, 0.1, 500);
camera.position.set(0, 0, 40);

const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
const bloom = new UnrealBloomPass(new THREE.Vector2(W, H), 1.3, 0.5, 0.45);
composer.addPass(bloom);

scene.add(new THREE.AmbientLight('#1a1a1a', 0.5));
const key = new THREE.DirectionalLight('#ffffff', 1.2);
key.position.set(5, 10, 7);
scene.add(key);
const rim = new THREE.PointLight('#34D399', 8, 50);
rim.position.set(-8, 4, -5);
scene.add(rim);
const fill = new THREE.PointLight('#F0BE63', 3, 40);
fill.position.set(8, -3, 5);
scene.add(fill);

const EMERALD = new THREE.Color('#34D399');
const AMBER = new THREE.Color('#F0BE63');
const WHITE = new THREE.Color('#ECEDE8');

function createMark() {
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  shape.lineTo(3.5, 0);
  shape.lineTo(3.5, 2.8);
  shape.lineTo(1.2, 2.8);
  shape.lineTo(1.2, 5.5);
  shape.lineTo(0, 5.5);
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, { depth: 0.6, bevelEnabled: true, bevelThickness: 0.08, bevelSize: 0.08, bevelSegments: 3 });
  const mat = new THREE.MeshPhysicalMaterial({
    color: EMERALD, metalness: 0.1, roughness: 0.15,
    clearcoat: 1.0, clearcoatRoughness: 0.1,
    emissive: EMERALD.clone().multiplyScalar(0.3)
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(-1.75, -2.75, -0.3);
  return mesh;
}
const mark = createMark();
mark.scale.setScalar(1.8);
scene.add(mark);

const TASK_COUNT = 1800;
const taskGeo = new THREE.BufferGeometry();
const taskPos = new Float32Array(TASK_COUNT * 3);
const taskCol = new Float32Array(TASK_COUNT * 3);
const taskSeed = new Float32Array(TASK_COUNT * 4);
for (let i = 0; i < TASK_COUNT; i++) {
  taskSeed[i*4] = Math.random();
  taskSeed[i*4+1] = Math.random();
  taskSeed[i*4+2] = Math.random();
  taskSeed[i*4+3] = Math.random();
  taskPos[i*3] = (Math.random() - 0.5) * 60;
  taskPos[i*3+1] = (Math.random() - 0.5) * 40;
  taskPos[i*3+2] = (Math.random() - 0.5) * 30;
  const c = Math.random() > 0.7 ? AMBER.clone() : WHITE.clone();
  taskCol[i*3] = c.r; taskCol[i*3+1] = c.g; taskCol[i*3+2] = c.b;
}
taskGeo.setAttribute('position', new THREE.BufferAttribute(taskPos, 3));
taskGeo.setAttribute('color', new THREE.BufferAttribute(taskCol, 3));
const taskMat = new THREE.PointsMaterial({ size: 0.12, vertexColors: true, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, opacity: 0.9 });
const tasks = new THREE.Points(taskGeo, taskMat);
scene.add(tasks);

const tools = [];
const toolNames = ['Email', 'Calendar', 'CRM', 'Accounts', 'Phone', 'Chat'];
for (let i = 0; i < 6; i++) {
  const angle = (i / 6) * Math.PI * 2;
  const radius = 10;
  const x = Math.cos(angle) * radius;
  const y = Math.sin(angle) * radius;
  const geo = new THREE.TorusGeometry(0.8, 0.15, 16, 32);
  const mat = new THREE.MeshStandardMaterial({ color: EMERALD, emissive: EMERALD, emissiveIntensity: 0.5, metalness: 0.8, roughness: 0.2 });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, y, 0);
  mesh.rotation.x = Math.PI / 2;
  scene.add(mesh);
  tools.push({ mesh, baseX: x, baseY: y, angle });
}

const streamGroups = [];
for (let i = 0; i < 6; i++) {
  const count = 100;
  const geo = new THREE.BufferGeometry();
  const pos = new Float32Array(count * 3);
  const seeds = [];
  for (let j = 0; j < count; j++) {
    seeds.push({ t: Math.random(), speed: 0.15 + Math.random() * 0.35 });
    pos[j*3] = 0; pos[j*3+1] = 0; pos[j*3+2] = 0;
  }
  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  const mat = new THREE.PointsMaterial({ size: 0.18, color: EMERALD, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, opacity: 0.85 });
  const pts = new THREE.Points(geo, mat);
  scene.add(pts);
  streamGroups.push({ pts, seeds });
}

function makeTextSprite(text, opts = {}) {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  const fontSize = opts.fontSize || 64;
  canvas.width = 2048;
  canvas.height = 512;
  ctx.fillStyle = opts.color || '#ECEDE8';
  ctx.font = `600 ${fontSize}px "Inter", "Inter Tight", system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 1024, 256);
  const tex = new THREE.CanvasTexture(canvas);
  tex.minFilter = THREE.LinearFilter;
  const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(canvas.width / 35, canvas.height / 35, 1);
  return sprite;
}

const titleSprite = makeTextSprite('Your next hire never sleeps.', { fontSize: 64 });
titleSprite.position.set(0, 6.5, 2);
titleSprite.visible = false;
scene.add(titleSprite);

const subSprite = makeTextSprite('A digital employee with its own computer, inbox and phone.', { fontSize: 28, color: '#9B9B95' });
subSprite.position.set(0, 4.8, 2);
subSprite.visible = false;
scene.add(subSprite);

const promiseSprite = makeTextSprite('Work handled. Time returned.', { fontSize: 80 });
promiseSprite.position.set(0, -2, 3);
promiseSprite.visible = false;
scene.add(promiseSprite);

const statSprite = makeTextSprite('UK owners estimate 11 hours a week on admin.', { fontSize: 24, color: '#F0BE63' });
statSprite.position.set(0, -5.5, 2);
statSprite.visible = false;
scene.add(statSprite);

const authLineGeo = new THREE.BufferGeometry();
const authLinePos = new Float32Array([0, 8, 1, 0, -8, 1]);
authLineGeo.setAttribute('position', new THREE.BufferAttribute(authLinePos, 3));
const authLineMat = new THREE.LineBasicMaterial({ color: EMERALD, transparent: true, opacity: 0 });
const authLine = new THREE.Line(authLineGeo, authLineMat);
scene.add(authLine);

function ease(t) { return t < 0.5 ? 4*t*t*t : 1 - Math.pow(-2*t+2, 3)/2; }
function lerp(a, b, t) { return a + (b - a) * t; }
function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }

window.__renderState = null;

function setTime(t) {
  t = clamp(t, 0, DUR);
  window.__renderState = t;

  if (t < 3) {
    camera.position.set(lerp(0, 0, ease(t/3)), lerp(2, 0, ease(t/3)), lerp(50, 40, ease(t/3)));
    camera.lookAt(0, 0, 0);
  } else if (t < 8) {
    const k = ease((t - 3) / 5);
    camera.position.set(lerp(0, 5, k), lerp(2, 0, k), lerp(40, 28, k));
    camera.lookAt(0, 0, 0);
  } else if (t < 14) {
    const k = ease((t - 8) / 6);
    camera.position.set(lerp(5, 0, k), lerp(0, 0, k), lerp(28, 35, k));
    camera.lookAt(0, 0, 0);
  } else if (t < 18) {
    const k = ease((t - 14) / 4);
    camera.position.set(lerp(0, 0, k), lerp(0, 0, k), lerp(35, 40, k));
    camera.lookAt(0, 0, 0);
  } else {
    const k = ease((t - 18) / 2);
    camera.position.set(0, 0, lerp(40, 50, k));
    camera.lookAt(0, 0, 0);
  }

  if (t < 3) {
    mark.rotation.y = lerp(Math.PI, 0, ease(t/3));
    mark.rotation.x = lerp(0.5, 0, ease(t/3));
    mark.material.emissiveIntensity = lerp(0.1, 0.3, ease(t/3));
    mark.visible = true;
  } else if (t < 8) {
    mark.rotation.y = Math.sin(t * 0.5) * 0.3;
    mark.rotation.x = Math.sin(t * 0.7) * 0.15;
    mark.material.emissiveIntensity = 0.3 + Math.sin(t * 2) * 0.15;
  } else if (t < 14) {
    const k = ease((t - 8) / 6);
    mark.scale.setScalar(lerp(1.8, 2.2, k));
    mark.rotation.y = lerp(0, Math.PI * 0.5, k);
    mark.material.emissiveIntensity = lerp(0.3, 0.6, k);
  } else {
    mark.rotation.y += 0.005;
    mark.scale.setScalar(2.2);
    mark.material.emissiveIntensity = 0.6;
  }

  const posArr = tasks.geometry.attributes.position.array;
  for (let i = 0; i < TASK_COUNT; i++) {
    const s = taskSeed[i*4];
    const phase = t * 0.3 + s * 10;
    if (t < 3) {
      posArr[i*3] = Math.cos(phase) * (15 + s * 20);
      posArr[i*3+1] = Math.sin(phase * 0.7) * (10 + s * 15);
      posArr[i*3+2] = Math.sin(phase * 1.3) * 8;
    } else if (t < 8) {
      const chaos = clamp((t - 3) / 2, 0, 1);
      posArr[i*3] = Math.cos(phase) * (15 + s * 20) * (1 + chaos * 2);
      posArr[i*3+1] = Math.sin(phase * 0.7) * (10 + s * 15) * (1 + chaos * 2);
      posArr[i*3+2] = Math.sin(phase * 1.3) * 8 * (1 + chaos);
    } else if (t < 14) {
      const k = ease((t - 8) / 6);
      const targetR = 1.5 + s * 4;
      const targetA = s * Math.PI * 2;
      const tx = Math.cos(targetA) * targetR;
      const ty = Math.sin(targetA) * targetR;
      posArr[i*3] = lerp(posArr[i*3], tx, k * 0.05);
      posArr[i*3+1] = lerp(posArr[i*3+1], ty, k * 0.05);
      posArr[i*3+2] = lerp(posArr[i*3+2], 0, k * 0.05);
    } else {
      const targetR = 1.5 + s * 4;
      const targetA = s * Math.PI * 2 + t * 0.2;
      posArr[i*3] = Math.cos(targetA) * targetR;
      posArr[i*3+1] = Math.sin(targetA) * targetR;
      posArr[i*3+2] = Math.sin(t + s * 5) * 0.5;
    }
  }
  tasks.geometry.attributes.position.needsUpdate = true;
  tasks.material.opacity = t < 8 ? 0.9 : 0.6;

  tools.forEach((tool, i) => {
    const a = tool.angle + Math.sin(t * 0.4 + i) * 0.15;
    const r = 10 + Math.sin(t * 0.6 + i * 1.2) * 0.8;
    tool.mesh.position.x = Math.cos(a) * r;
    tool.mesh.position.y = Math.sin(a) * r;
    tool.mesh.rotation.z = t * 0.3 + i;
    tool.mesh.material.emissiveIntensity = 0.3 + Math.sin(t * 2 + i) * 0.2;
  });

  streamGroups.forEach((stream, i) => {
    const posArr2 = stream.pts.geometry.attributes.position.array;
    for (let j = 0; j < stream.seeds.length; j++) {
      const sd = stream.seeds[j];
      sd.t = (sd.t + sd.speed * 0.016) % 1;
      const tt = sd.t;
      const tx = tools[i].baseX, ty = tools[i].baseY, tz = 0;
      posArr2[j*3] = lerp(0, tx, tt) + (Math.random() - 0.5) * 0.3;
      posArr2[j*3+1] = lerp(0, ty, tt) + (Math.random() - 0.5) * 0.3;
      posArr2[j*3+2] = lerp(0, tz, tt) + (Math.random() - 0.5) * 0.3;
    }
    stream.pts.geometry.attributes.position.needsUpdate = true;
    stream.pts.material.opacity = t > 8 && t < 18 ? 0.85 : 0;
  });

  if (t > 2.5 && t < 7) {
    titleSprite.visible = true;
    titleSprite.material.opacity = t < 3.5 ? ease((t - 2.5) / 1) : t > 5.5 ? 1 - ease((t - 5.5) / 1.5) : 1;
  } else if (t >= 7 && t < 14) {
    titleSprite.visible = false;
    subSprite.visible = true;
    subSprite.material.opacity = t < 8 ? ease((t - 7) / 1) : t > 12 ? 1 - ease((t - 12) / 2) : 1;
    statSprite.visible = true;
    statSprite.material.opacity = t < 8.5 ? ease((t - 8) / 1) : t > 13 ? 1 - ease((t - 13) / 1) : 1;
  } else {
    titleSprite.visible = false;
    subSprite.visible = false;
    statSprite.visible = false;
  }

  if (t > 15 && t < 20) {
    promiseSprite.visible = true;
    promiseSprite.material.opacity = t < 16 ? ease((t - 15) / 1) : 1;
    promiseSprite.scale.setScalar(1 + ease((t - 15) / 5) * 0.3);
  } else {
    promiseSprite.visible = false;
    promiseSprite.scale.setScalar(1);
  }

  if (t > 13 && t < 18) {
    authLineMat.opacity = t < 14 ? ease((t - 13) / 1) : t > 16 ? 1 - ease((t - 16) / 2) : 0.6;
  } else {
    authLineMat.opacity = 0;
  }

  bloom.strength = 1.2 + Math.sin(t * 0.8) * 0.3;
  composer.render();
}

window.setTime = setTime;
window.__W = W; window.__H = H; window.__FPS = FPS; window.__DUR = DUR;

setTime(0);
</script>
</body>
</html>
