{"content":"const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');

const W = 1920, H = 1080, FPS = 24, DUR = 20;
const TOTAL_FRAMES = W * H * FPS * DUR;
const FRAME_COUNT = FPS * DUR;
const OUT_DIR = path.join(__dirname, 'frames');
if (!fs.existsSync(OUT_DIR)) fs.mkdirSync(OUT_DIR, { recursive: true });

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu', '--enable-webgl', '--hide-scrollbars']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: W, height: H, deviceScaleFactor: 1 });

  const fileUrl = 'file://' + path.join(__dirname, 'hero.html');
  console.log('Loading', fileUrl);
  await page.goto(fileUrl, { waitUntil: 'networkidle0', timeout: 120000 });
  console.log('Page loaded');

  // Wait for three.js scene to be ready
  await page.waitForFunction(() => typeof window.setTime === 'function', { timeout: 120000 });
  console.log('Scene ready');

  // Verify we can render
  await page.evaluate(() => window.setTime(0));
  await page.waitForTimeout(500);

  let rendered = 0;
  for (let f = 0; f < FRAME_COUNT; f++) {
    const t = f / FPS;
    await page.evaluate((tt) => window.setTime(tt), t);
    await page.waitForTimeout(8); // small settle
    const buf = await page.screenshot({ type: 'jpeg', quality: 95, clip: { x: 0, y: 0, width: W, height: H } });
    const name = `f${String(f).padStart(4, '0')}.jpg`;
    fs.writeFileSync(path.join(OUT_DIR, name), buf);
    rendered++;
    if (rendered % 24 === 0) {
      const pct = Math.round((rendered / FRAME_COUNT) * 100);
      console.log(`Rendered ${rendered}/${FRAME_COUNT} (${pct}%)`);
    }
  }

  console.log(`Done. ${rendered} frames saved to ${OUT_DIR}`);
  await browser.close();
})().catch(err => {
  console.error('Fatal:', err);
  process.exit(1);
});
